WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS is_new_session FROM device_readings), islands AS (SELECT id, device_code, reading_ts, temp_c, humidity, status_bits, firmware, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps), prev_events AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM islands), gaps AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL '20' MINUTE THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), sessions_device_readings AS (SELECT id, device_code, reading_ts, humidity, firmware, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps), remaining_keys AS (SELECT id FROM sessions_device_readings EXCEPT SELECT id FROM device_readings WHERE humidity < 72), kept_rows AS (SELECT s.* FROM sessions_device_readings s INNER JOIN remaining_keys k ON s.id = k.id), with_windows AS (SELECT id, reading_ts, firmware, session_no, SUM(session_no) OVER (PARTITION BY device_code) AS device_code_sum_session_no, ROUND(humidity / SUM(humidity) OVER (PARTITION BY device_code), 4) AS humidity_share, ROUND(humidity / SUM(humidity) OVER (PARTITION BY device_code), 4) AS humidity_share_2, MIN(session_no) OVER (PARTITION BY device_code) AS device_code_min_session_no FROM kept_rows WHERE humidity < 50) SELECT CASE WHEN device_code_min_session_no >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS device_code_min_session_no_tier, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes, APPROX_PERCENTILE(device_code_sum_session_no, 0.5) AS device_code_sum_session_no_p50, GROUPING(CASE WHEN device_code_min_session_no >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_level FROM with_windows GROUP BY CUBE (CASE WHEN device_code_min_session_no >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY device_code_min_session_no_tier
